      "id": "R7.1.0(1)",
      "title": "safety architecture",
      "text": "The PCA pump shall implement a safety architecture that separates normal operation from fault detection and response."
    },
    {
      "id": "R7.2.0(1)",
      "title": "complete pump stroke",
      "text": "When the stop button is pressed, the current pump stroke shall be completed prior to stopping the pump."
    },
    {
      "id": "R7.2.0(2)",
      "title": "continuous reverse delivery",
      "text": "During normal use and/or single fault condition of the equipment, continuous reverse delivery shall not be possible."
    },
    {
      "id": "R7.2.0(3)",
      "title": "air-in-line alarm",
      "text": "An air-in-line alarm shall be triggered by the pump if detectable air bubbles are infused into the patient."
    },
    {
      "id": "R7.2.0(4)",
      "title": "upstream occlusion alarm",
      "text": "An upstream occlusion alarm shall be triggered when the pump senses an upstream (drug reservoir side) occlusion exceeding Puo = 1 psi."
    },
    {
      "id": "R7.2.0(5)",
      "title": "downstream occlusion alarm",
      "text": "A downstream occlusion alarm shall be triggered if the pump senses a downstream (patient side) occlusion exceeding Pdo = 10 psi."
    },
    {
      "id": "R7.2.0(6)",
      "title": "occlusion alarm",
      "text": "When an occlusion alarm occurs, the pump shall be stopped immediately without completing the current pump stroke."
    },
    {
      "id": "R7.2.0(7)",
      "title": "empty-reservoir alarm",
      "text": "When an empty-reservoir alarm occurs, the current pump stroke shall be completed prior to stopping the pump."
    },
    {
      "id": "R7.2.0(8)",
      "title": "open door alarm",
      "text": "An open door alarm shall be triggered when the reservoir door is opened while the pump is not stopped."
    }
